49	        hooks: composeHooks(new TaskBoardGuard(workspaceRoot, record.feature), new SpecContract(workspaceRoot)),
50	        systemPrompt: await ctx.withInstructions(record, await ctx.withMemories(record, await ctx.withMap(record, implementPrompt(record.feature, workspaceRoot, ctx.verifyRules())))),
