91	        // The entry contract answers on the write that broke it, so a bad anchor never reaches a planner's prompt.
92	        hooks: composeHooks(new ScopeGuard(workspaceRoot, docsMapScope(record.files ?? [])), new DocsMapContract(workspaceRoot)),
93	        systemPrompt: await ctx.withInstructions(record, await ctx.withMemories(record, docsMapPrompt(workspaceRoot))),
94	        toolNames: DOCS_MAP_TOOLS,
95	      }
96	    }
97	    case 'reconcile': {
98	      if (!record.feature) throw new Error('A reconcile session needs a feature name')
99	      return {
100	        hooks: composeHooks(
101	          new ScopeGuard(workspaceRoot, reconcileScope(record.feature)),
102	          new SpecContract(workspaceRoot),
103	          new ScenarioContextContract(workspaceRoot, record.feature),
104	        ),
105	        systemPrompt: await ctx.withInstructions(record, await ctx.withMemories(record, await ctx.withMap(record, reconcilePrompt(record.feature, workspaceRoot)))),
106	        toolNames: RECONCILE_TOOLS,
107	      }
108	    }
109	    case 'cleanup': {
110	      if (!record.feature || !record.files) throw new Error('A cleanup session needs a feature name and the files to split')
