112	        hooks: new ScopeGuard(workspaceRoot, cleanupScope(record.files)),
113	        systemPrompt: await ctx.withInstructions(record, await ctx.withMemories(record, cleanupPrompt(record.feature, workspaceRoot, ctx.cleanupLimits()))),
114	        toolNames: CLEANUP_TOOLS,
115	      }
116	    }
