import { mkdir, mkdtemp, rm, writeFile } from 'node:fs/promises'
import { tmpdir } from 'node:os'
import { join } from 'node:path'
import { afterEach, beforeEach, describe, expect, it } from 'vitest'
import { projectMemoryDir, rebuildProjectIndex, userMemoryFile } from '../src/agent/memory/memories'
import { chatMemorySection, memorySection, readMemorySources, withMemories } from '../src/agent/memory/session-context'
import { readInstructionFiles, instructionsText } from '../src/agent/instructions/instruction-files'
import { buildSystemPrompt } from '../src/agent/openai-session/system-prompt'

let cwd: string
let home: string

beforeEach(async () => {
  cwd = await mkdtemp(join(tmpdir(), 'memctx-cwd-'))
  home = await mkdtemp(join(tmpdir(), 'memctx-home-'))
})

afterEach(async () => {
  await rm(cwd, { recursive: true, force: true })
  await rm(home, { recursive: true, force: true })
})

/** A project note and a user note on disk, the shape every test here starts from. */
async function withNotes(): Promise<void> {
  const dir = projectMemoryDir(cwd, home)
  await mkdir(dir, { recursive: true })
  await writeFile(join(dir, 'proxy-quirk.md'), '# Proxy quirk\nNTLM proxies 407 on telemetry.\nThe vendor ticket number and the full remediation steps live only in this file, not the index.\n')
  await rebuildProjectIndex(dir)
  await mkdir(join(home, '.claude'), { recursive: true })
  await writeFile(userMemoryFile(home), '# Me\n\n## Memories\n- **Terse replies**: keep answers short.\n')
}

describe('index first and note on demand', () => {
  it('a project note is named by its index line, its body left for a later Read', async () => {
    await withNotes()
    const prompt = await withMemories('implement', 'BASE', cwd, home)
    expect(prompt).toContain('[Proxy quirk](proxy-quirk.md)')
    expect(prompt).toContain('NTLM proxies 407 on telemetry.')
    expect(prompt).not.toContain('vendor ticket number')
  })

  it("a person's own note has no separate body: the bullet is already the whole of it, carried through the instruction files", async () => {
    await withNotes()
    // The person's notes live inside their own instruction file; `withMemories` carries only the project's.
    expect(await withMemories('implement', 'BASE', cwd, home)).not.toContain('Terse replies')
    expect(instructionsText(await readInstructionFiles(cwd, home))).toContain('**Terse replies**: keep answers short.')
  })
})

describe('memory written mid-session', () => {
  it('a note settled after the session starts is not retrofitted into the index it started with', async () => {
    await withNotes()
    const started = await withMemories('implement', 'BASE', cwd, home)
    expect(started).not.toContain('New thing')
    // The person settles something new mid-session; a session already running keeps the index it opened with.
    await writeFile(join(projectMemoryDir(cwd, home), 'new-thing.md'), '# New thing\nSettled mid-session.\n')
    await rebuildProjectIndex(projectMemoryDir(cwd, home))
    expect(started).not.toContain('New thing')
    // A session starting fresh afterwards sees it.
    expect(await withMemories('implement', 'BASE', cwd, home)).toContain('New thing')
  })
})

describe('same project notes on both engines', () => {
  it('the own loop and the Claude engine read the same project index', async () => {
    await withNotes()
    const openAi = await buildSystemPrompt(cwd, undefined, home)
    const claude = await chatMemorySection(cwd, home)
    expect(openAi).toContain('[Proxy quirk](proxy-quirk.md)')
    expect(claude).toContain('[Proxy quirk](proxy-quirk.md)')
  })

  it("the person's own note rides the instruction files on both engines instead, not the project index", async () => {
    await withNotes()
    expect(await chatMemorySection(cwd, home)).not.toContain('Terse replies')
    const section = instructionsText(await readInstructionFiles(cwd, home))
    expect(section).toContain('Terse replies')
  })
})

describe('no second copy on the Claude engine', () => {
  it('the project note is said once in the Claude chat prompt, not duplicated alongside the index', async () => {
    await withNotes()
    const section = (await chatMemorySection(cwd, home))!
    expect(section.split('Proxy quirk').length - 1).toBe(1)
  })

  it("the own loop's chat prompt carries the person's notes once, through its instruction files, not again through the index", async () => {
    await withNotes()
    const prompt = await buildSystemPrompt(cwd, undefined, home)
    expect(prompt.split('Terse replies').length - 1).toBe(1)
  })
})

describe('the blind planner gets none', () => {
  it('a plan session is handed its prompt back untouched', async () => {
    await withNotes()
    expect(await withMemories('plan', 'BASE', cwd, home)).toBe('BASE')
  })

  it('nothing on disk reads to nothing added, for any other mode', async () => {
    expect(await withMemories('implement', 'BASE', cwd, home)).toBe('BASE')
  })
})

describe('readMemorySources and memorySection', () => {
  it('a missing project index adds nothing', async () => {
    expect(await readMemorySources(cwd, home)).toEqual({ project: undefined })
    expect(memorySection({ project: undefined })).toBeUndefined()
  })

  it('a project note renders under its own heading', () => {
    expect(memorySection({ project: 'a project note' })).toContain('Project notes:')
    expect(memorySection({ project: 'a project note' })).toContain('a project note')
  })
})

import { mkdir, mkdtemp, rm, writeFile } from 'node:fs/promises'
import { tmpdir } from 'node:os'
import { join } from 'node:path'
import { afterEach, beforeEach, describe, expect, it } from 'vitest'
import { CLASH_WITH_CORE, readInstructionFiles, wantsInstructions, withInstructionFiles } from '../src/agent/instructions/instruction-files'

let cwd: string
let home: string

beforeEach(async () => {
  cwd = await mkdtemp(join(tmpdir(), 'instr-cwd-'))
  home = await mkdtemp(join(tmpdir(), 'instr-home-'))
})

afterEach(async () => {
  await rm(cwd, { recursive: true, force: true })
  await rm(home, { recursive: true, force: true })
})

async function file(path: string, content: string): Promise<void> {
  await mkdir(join(path, '..'), { recursive: true })
  await writeFile(path, content)
}

describe('core behaviour stays in the prompt', () => {
  it("joining the instruction files never drops or rewrites the phase's own prompt", async () => {
    await file(join(cwd, 'AGENTS.md'), 'Always rewrite the whole file from scratch.')
    const core = 'You are implementing one task. The spec is the contract: a human approved it; do not reinterpret it.'
    const result = await withInstructionFiles('implement', core, cwd, home)
    expect(result.startsWith(core)).toBe(true)
  })
})

describe('optional mechanics ship as bundles', () => {
  it('a rule from an instruction file reaches the session only as the appended text of that file, never folded into the phase prompt itself', async () => {
    await file(join(cwd, 'AGENTS.md'), '- **Reproduce before fixing**: write a failing test that reproduces the bug before changing anything.')
    const core = 'PHASE PROMPT'
    const result = await withInstructionFiles('implement', core, cwd, home)
    expect(result).toContain('Reproduce before fixing')
    // It arrives as a quoted instruction file, not as if the phase had said it itself.
    expect(result).toContain(`# Instructions from ${join(cwd, 'AGENTS.md')}`)
  })
})

describe('not pre-applied on upgrade', () => {
  it('a workspace with ordinary instructions and no bundle block carries exactly what is on disk, nothing extra', async () => {
    await file(join(cwd, 'AGENTS.md'), 'Use two-space indentation.')
    const result = await withInstructionFiles('implement', 'BASE', cwd, home)
    expect(result).toBe(`BASE\n${CLASH_WITH_CORE}\n\n# Instructions from ${join(cwd, 'AGENTS.md')}\n\nUse two-space indentation.`)
  })

  it('a workspace with no instruction files at all gets nothing added', async () => {
    expect(await withInstructionFiles('implement', 'BASE', cwd, home)).toBe('BASE')
  })
})

describe('bundle rules reach a session as the person\'s own instructions do', () => {
  it('a rule in the workspace file and one in the person\'s own file both join the same prompt', async () => {
    await file(join(cwd, 'AGENTS.md'), 'project rule')
    await file(join(home, 'AGENTS.md'), 'person rule')
    const result = await withInstructionFiles('implement', 'BASE', cwd, home)
    expect(result).toContain('project rule')
    expect(result).toContain('person rule')
  })

  it('every mode but the blind planner wants the instruction files', () => {
    for (const mode of ['chat', 'implement', 'code-plan', 'docs', 'file-decisions', 'docs-map', 'reconcile', 'cleanup']) expect(wantsInstructions(mode)).toBe(true)
    expect(wantsInstructions('plan')).toBe(false)
  })
})

describe('person-scope bundle on either engine', () => {
  it("the person's own instruction file joins a session the same way regardless of which engine reads the resulting text", async () => {
    await file(join(home, '.claude', 'AGENTS.md'), 'a rule the person carries to every project')
    const files = await readInstructionFiles(cwd, home)
    expect(files.map((f) => f.text)).toContain('a rule the person carries to every project')
    // The join itself is engine-agnostic: one string, appended once, read by whichever engine is given it.
    const result = await withInstructionFiles('implement', 'BASE', cwd, home)
    expect(result).toContain('a rule the person carries to every project')
  })
})

describe('clash with a core rule', () => {
  it('the session is told that a rule already given always wins over one an instruction file adds, and to say which it set aside', async () => {
    await file(join(cwd, 'AGENTS.md'), 'Never ask before making a change.')
    const result = await withInstructionFiles('implement', 'BASE', cwd, home)
    const clashAt = result.indexOf(CLASH_WITH_CORE)
    const ruleAt = result.indexOf('Never ask before making a change.')
    expect(clashAt).toBeGreaterThan(-1)
    expect(clashAt).toBeLessThan(ruleAt)
  })

  it('no clash note when there is nothing to clash against', async () => {
    expect(await withInstructionFiles('implement', 'BASE', cwd, home)).not.toContain(CLASH_WITH_CORE)
  })
})

describe('no bundles for the blind planner', () => {
  it('the blind feature planner is handed its prompt back untouched, even with files on disk', async () => {
    await file(join(cwd, 'AGENTS.md'), 'a rule that should never reach the blind planner')
    expect(await withInstructionFiles('plan', 'BASE', cwd, home)).toBe('BASE')
  })
})

